  // Get schedule with movie info and availability
  ScheduleDetails getScheduleDetailsView (int scheduleId) throws ScheduleNotFoundException;

  // Get all schedules with details
  ScheduleDetails[] getAllSchedulesWithDetails ();

  // seatIds parameter contains schedule_list_seat_ids
  int createBooking (int customerId, String sessionToken, int scheduleId, int[] scheduleListSeatIds) throws AuthenticationException, SeatNotAvailableException, BookingException;

  // Get booking details
  Booking getBookingDetails (int bookingId) throws BookingException;

  // Get all bookings for a customer
  Booking[] getCustomerBookings (int customerId, String sessionToken) throws AuthenticationException;

  // Cancel a booking (must be customer's own booking)
  void cancelBooking (int customerId, String sessionToken, int bookingId) throws AuthenticationException, BookingException;

  // Confirm payment for a booking (changes status from pending to confirmed)
  void confirmPayment (int customerId, String sessionToken, int bookingId) throws AuthenticationException, BookingException;

  // Modify booking (change seats, before confirmation)
  void updateBooking (int customerId, String sessionToken, int bookingId, int[] newScheduleListSeatIds) throws AuthenticationException, BookingException, SeatNotAvailableException;

  // Update booking status
  void updateBookingStatus (int customerId, String sessionToken, int bookingId, String status) throws AuthenticationException, BookingException;

  // Get customer's booking history (completed bookings)
  Booking[] getBookingHistory (int customerId, String sessionToken) throws AuthenticationException;

  // Get customer's active bookings (pending/confirmed)
  Booking[] getActiveBookings (int customerId, String sessionToken) throws AuthenticationException;

  // Get booking with full details
  BookingDetails getBookingDetailsView (int customerId, String sessionToken, int bookingId) throws AuthenticationException, BookingException;

  // Get all customer's bookings with details
  BookingDetails[] getCustomerBookingsWithDetails (int customerId, String sessionToken) throws AuthenticationException;

  // Process payment for booking
  int processPayment (int customerId, String sessionToken, int bookingId, double amount, String paymentMethod, String transactionId) throws AuthenticationException, BookingException, PaymentException;

  // Get payment details
  Payment getPaymentDetails (int customerId, String sessionToken, int paymentId) throws AuthenticationException, PaymentNotFoundException;

  // Get all payments for customer
  Payment[] getCustomerPayments (int customerId, String sessionToken) throws AuthenticationException;

  // Get payment for specific booking
  Payment getBookingPayment (int customerId, String sessionToken, int bookingId) throws AuthenticationException, BookingException;

  // Get payment with full context
  PaymentDetails getPaymentDetailsView (int customerId, String sessionToken, int paymentId) throws AuthenticationException, PaymentNotFoundException;

  // Get all customer's payments with details
  PaymentDetails[] getCustomerPaymentsWithDetails (int customerId, String sessionToken) throws AuthenticationException;
